/* ── icons — the project's own vector assets ──────────────────────── */
/* August's icon system is lucide-react; this module holds the three things
 * lucide cannot supply:
 *
 *   1. The third-party BRAND MARKS (Simple Icons, CC0) for the ~80 logos the
 *      file-icon and tool-icon tables paint. They used to come from the
 *      `react-icons/si` BARREL — one 4.9 MB module holding ~3,000 icons, of
 *      which the desktop app used 80. The barrel put ~3,000 icon components
 *      in the module graph and made every build re-parse 4.9 MB of source.
 *      The path data below was extracted VERBATIM from the Simple Icons
 *      definitions shipped in react-icons@5.5.0
 *      (node_modules/react-icons/si/index.mjs), so the glyphs render exactly
 *      as the barrel's did.
 *   2. The lucide `Copy` glyph as an HTML STRING, for the one consumer that
 *      cannot use a React component (the markdown code-block header is raw
 *      HTML injected with dangerouslySetInnerHTML).
 *   3. The upload PROGRESS RING — a determinate arc, which is a graphic
 *      rather than an icon, and therefore has no lucide equivalent.
 *
 * COLOURS do not live here: each caller owns its brand colour, because the
 * colour is part of the mark's MEANING (a Python mark is not a Ruby mark),
 * not part of the artwork.
 *
 * To add a brand mark, take its `d` attribute from
 * https://simpleicons.org, add an export below, and point the icon table at
 * it.  */

import type { CSSProperties, ReactElement, SVGProps } from 'react';
import { cn } from '@/lib/utils';

/* ── brand marks ──────────────────────────────────────────────────── */

/** The prop contract react-icons' components exposed, and that the icon
 *  tables in lib/file-icon.ts and lib/tool-icon.ts are typed against. */
export type BrandMarkProps = { size?: number; color?: string } & SVGProps<SVGSVGElement>;

export type BrandMark = (props: BrandMarkProps) => ReactElement;

/** One component factory for every mark: an <svg> filled with currentColor
 *  (Simple Icons are solid shapes), sized by `size` and tinted by `color`
 *  exactly as react-icons did — `role="img"` and a 24×24 viewBox included.
 *
 *  The mark is a path STRING, not a pre-built element: nothing is allocated
 *  at module load, and the table stays plain data the bundler can read. */
function makeMark(d: string): BrandMark {
  return function BrandMarkComponent(props) {
    // The colour prop is deliberately NOT destructured out: react-icons
    // passed the whole props object to the <svg>, so the colour landed BOTH
    // as the SVG color attribute and as style.color. Keeping it in the rest
    // of the props reproduces that byte for byte.
    const { size, className, style, ...rest } = props;
    const computedSize = size || '1em';
    // The caller's style wins over the `color` prop, exactly as react-icons'
    // IconBase did (`{ color: props.color, ...props.style }`).
    const mergedStyle = { color: props.color, ...style };
    return (
      <svg
        stroke="currentColor"
        fill="currentColor"
        strokeWidth={0}
        role="img"
        viewBox="0 0 24 24"
        {...rest}
        className={className}
        style={mergedStyle}
        height={computedSize}
        width={computedSize}
        xmlns="http://www.w3.org/2000/svg"
      >
        <path d={d} />
      </svg>
    );
  };
}

