/* ── the lucide copy glyph, as markup ─────────────────────────────── */

/** Lucide's `Copy` glyph (lucide-react 0.439.0), as an HTML string.
 *
 *  The markdown code-block header is produced by marked's renderer and
 *  injected with dangerouslySetInnerHTML, so its copy affordance cannot be a
 *  React component — the geometry lives here instead of being hand-copied
 *  into the renderer, which is where it used to drift.  */
export const COPY_ICON_SVG =
  '<svg class="size-3 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
  'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
  '<rect width="14" height="14" x="8" y="8" rx="2" ry="2" /><path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2" />' +
  '</svg>';

/* ── the upload progress ring ─────────────────────────────────────── */

export interface ProgressRingProps {
  /** Outer diameter in px. Default 44. */
  size?: number;
  /** Stroke width in px. Default 3. */
  stroke?: number;
  /** 0–100. OMIT it for the indeterminate state. */
  progress?: number;
  /** Classes for the <svg> itself (position, rotation, spin). */
  className?: string;
  /** Classes for the track circle behind the arc. */
  trackClassName?: string;
  /** Classes for the arc. */
  arcClassName?: string;
  /** Inline style for the <svg> (e.g. a custom animation duration). */
  style?: CSSProperties;
}

/** A determinate progress arc, or an indeterminate sweep when `progress` is
 *  omitted. A graphic, not an icon: no icon library draws a partial ring. */
export function ProgressRing({
  size = 44,
  stroke = 3,
  progress,
  className,
  trackClassName = 'text-muted-foreground/25',
  arcClassName = 'text-primary',
  style,
}: ProgressRingProps) {
  const pct = Math.min(100, Math.max(0, progress ?? 0));
  // FileReader often skips progress events for small files — use an
  // indeterminate arc until there is a real percentage.
  const determinate = progress !== undefined && pct > 0;
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = determinate ? circumference * (1 - pct / 100) : circumference * 0.75;

  return (
    <svg
      width={size}
      height={size}
      className={cn('absolute inset-0 -rotate-90', !determinate && 'animate-spin', className)}
      style={style}
      aria-hidden
    >
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke="currentColor"
        strokeWidth={stroke}
        className={trackClassName}
      />
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke="currentColor"
        strokeWidth={stroke}
        strokeLinecap="round"
        strokeDasharray={circumference}
        strokeDashoffset={offset}
        className={cn(
          arcClassName,
          determinate && 'transition-[stroke-dashoffset] duration-150 ease-out',
        )}
      />
    </svg>
  );
}
